package nl.smartstreamlabs.sbwdroneconfig;
import com.atsuishio.superbwarfare.entity.vehicle.base.GeoVehicleEntity;
import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.network.chat.Component;import net.minecraft.network.syncher.*;import net.minecraft.nbt.*;import net.minecraft.world.phys.*;import net.minecraft.util.Mth;import java.util.*;
/** Native SBW wheel vehicle and inventory; server owns every deployment/load/fire decision. */
public class Mpl01Entity extends GeoVehicleEntity implements PatriotLauncher {
 public enum Phase {TRANSPORT,DEPLOYING,DEPLOYED,RETRACTING}
 private static final EntityDataAccessor<Integer> PHASE=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.INT),POSE=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.INT),AMMO=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.INT),FIRED=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.INT),SLOT=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.INT);
 private static final EntityDataAccessor<Boolean> PARK=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.BOOLEAN);
 private static final EntityDataAccessor<String> TARGET=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.STRING),STATUS=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.STRING);
 private static final EntityDataAccessor<CompoundTag> CONTACTS=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.COMPOUND_TAG),JACKS=SynchedEntityData.defineId(Mpl01Entity.class,EntityDataSerializers.COMPOUND_TAG);
 private UUID owner;private String ownerName="";private int progress;private long nextShot;private final long[] lastActions={-100,-100,-100,-100,-100,-100,-100};private float oldPose,visualPose;private Vec3 lastVisual;private double wheel,oldWheel;private float steer,oldSteer;
 public Mpl01Entity(EntityType<? extends Mpl01Entity> t,Level l){super(t,l);}
 @Override protected void defineSynchedData(){super.defineSynchedData();entityData.define(PHASE,0);entityData.define(POSE,0);entityData.define(AMMO,0);entityData.define(FIRED,0);entityData.define(SLOT,0);entityData.define(PARK,false);entityData.define(TARGET,"");entityData.define(STATUS,"NO TARGET");entityData.define(CONTACTS,new CompoundTag());entityData.define(JACKS,new CompoundTag());}
 @Override public net.minecraft.world.inventory.AbstractContainerMenu createMenu(int id,net.minecraft.world.entity.player.Inventory inv,Player p){return new MplServiceMenu(id,inv,this);}
 @Override public void openMenu(Player p){openCustomInventoryScreen(p);}
 @Override public void openCustomInventoryScreen(Player p){if(p instanceof ServerPlayer sp&&DefenseData.allowed(sp.serverLevel(),owner,ownerName,sp)&&sp.distanceToSqr(this)<=64)net.minecraftforge.network.NetworkHooks.openScreen(sp,new SimpleMenuProvider((id,inv,who)->new MplServiceMenu(id,inv,this),Component.translatable("mpl01.service")),buf->buf.writeInt(getId()));}
 public UUID defenseId(){return getUUID();}public UUID defenseOwner(){return owner;}public String defenseOwnerName(){return ownerName;}public ServerLevel defenseLevel(){return(ServerLevel)level();}public Vec3 defensePosition(){return position();}public Entity defenseEntity(){return this;}
 public boolean defenseAvailable(){return !isWreck()&&phase()==Phase.DEPLOYED&&getEnergy()>0&&ammoMask()!=0&&level().getGameTime()>=nextShot;}
 public boolean defenseRequest(ServerPlayer actor,UUID goal,UUID radar){if(!(level()instanceof ServerLevel l)||!DefenseData.get(l).radarAllows(l,radar,getUUID(),actor,actor==null)||!defenseAvailable())return false;var t=l.getEntity(goal);if(!hostile(t))return false;entityData.set(TARGET,goal.toString());if(getItem(selectedSlot()).getItem()!=AddonItems.PM01.get())for(int i=0;i<4;i++)if(getItem(i).getItem()==AddonItems.PM01.get()){entityData.set(SLOT,i);break;}return fireImpl(actor);}
 @Override public void remove(RemovalReason reason){if(level()instanceof ServerLevel l&&!reason.shouldSave())DefenseData.get(l).remove(l,getUUID());super.remove(reason);}
 public UUID owner(){return owner;}public String ownerName(){return ownerName;}public Phase phase(){return Phase.values()[Mth.clamp(entityData.get(PHASE),0,3)];}public boolean parked(){return entityData.get(PARK)||phase()!=Phase.TRANSPORT;}public int selectedSlot(){return entityData.get(SLOT);}public String selectedTarget(){return entityData.get(TARGET);}public String status(){return entityData.get(STATUS);}public CompoundTag contacts(){return entityData.get(CONTACTS);}public int ammoMask(){return entityData.get(AMMO);}public boolean fired(int i){return(entityData.get(FIRED)&(1<<i))!=0;}public float pose(float p){return Mth.lerp(p,oldPose,visualPose);}public double wheel(float p){return oldWheel+(wheel-oldWheel)*p;}public float steer(float p){return Mth.lerp(p,oldSteer,steer);}
 public void jackOffset(int i,float v){var n=entityData.get(JACKS).copy();n.putFloat("J"+i,v);if(!n.equals(entityData.get(JACKS)))entityData.set(JACKS,n);}public float jackOffset(int i){return entityData.get(JACKS).getFloat("J"+i);}
 public void claimOwner(Player p){if(owner==null){owner=p.getUUID();ownerName=p.getScoreboardName();}}
 public boolean operator(ServerPlayer p){return p!=null&&p.isAlive()&&!p.isSpectator()&&!InjuryServer.cannotOperate(p)&&p.getVehicle()==this&&(getSeatIndex(p)==1||getSeatIndex(p)==0&&p.getUUID().equals(owner))&&!isWreck();}
 @Override public int getContainerSize(){return 5;}@Override public int getMaxStackSize(){return 1;}@Override public boolean canPlaceItem(int i,ItemStack s){return i>=0&&i<5&&getItem(i).isEmpty()&&(i==4?s.getItem()instanceof com.atsuishio.superbwarfare.item.material.BatteryItem:s.getItem()==AddonItems.PM01.get())&&phase()!=Phase.DEPLOYING&&phase()!=Phase.RETRACTING;}
 @Override public void setChanged(){super.setChanged();if(!level().isClientSide)syncAmmo();}
 private void syncAmmo(){int mask=0;for(int i=0;i<4;i++)if(getItem(i).getItem()==AddonItems.PM01.get())mask|=1<<i;entityData.set(AMMO,mask);}
 @Override public double getTargetSpeed(){return parked()?0:super.getTargetSpeed();}
 @Override public void processInput(short keys){super.processInput(parked()?(short)16:(short)(keys&~128));}
 @Override public void travel(){if(parked()){super.processInput((short)16);setPower(0);setDeltaRot(0);var v=getDeltaMovement();setDeltaMovement(0,v.y,0);}super.travel();}
 @Override public boolean canShoot(LivingEntity p){return false;}@Override public int getTurretControllerIndex(){return -1;}
 private void status(String s){if(!status().equals(s))entityData.set(STATUS,s);}
 public org.joml.Matrix4d launcher(float p){return Mpl01Frames.launcher(getVehicleTransform(p),Mpl01Frames.angle(pose(p)));}
 public Vec3 mount(int i,float p){return Mpl01Frames.point(launcher(p),Mpl01Frames.mount(i));}public Vec3 launchDirection(float p){return Mpl01Frames.forward(launcher(p));}
 public Entity target(){if(!(level()instanceof ServerLevel l))return null;try{return l.getEntity(UUID.fromString(selectedTarget()));}catch(IllegalArgumentException ex){return null;}}
 public static boolean airDrone(Entity t){return Adv01Targets.drone(t)&&!t.onGround()&&!t.isPassenger()&&!(t instanceof VatagEntity)&&!(t instanceof MedicalTrailerEntity)&&!(t instanceof Adv01Entity)&&!(t instanceof Mj03Entity)&&!(t instanceof Mpl01Entity)&&(!(t instanceof Hx2Entity h)||h.flying()&&h.mount()==null)&&(!(t instanceof Id01Entity i)||i.mode()!=Id01Entity.Mode.STANDBY&&i.mode()!=Id01Entity.Mode.DISABLED);}
 public boolean hostile(Entity t){return level()instanceof ServerLevel l&&airDrone(t)&&Adv01Targets.relation(l,owner,ownerName,t)==Adv01Targets.HOSTILE&&distanceToSqr(t)<=Mpl01Config.RANGE.get()*Mpl01Config.RANGE.get();}
 private void scan(){var l=(ServerLevel)level();var linked=DefenseData.get(l).site(getUUID());if(linked!=null&&linked.radar!=null){var radar=DefenseData.get(l).radar(l,linked.radar);if(radar!=null&&radar.active()){var data=new CompoundTag();var shared=radar.contacts.copy();for(var contact:shared){var n=(CompoundTag)contact;var current=l.getEntity(n.getUUID("UUID"));if(current!=null)n.putDouble("Distance",distanceTo(current));}data.put("Entries",shared);if(!data.equals(entityData.get(CONTACTS)))entityData.set(CONTACTS,data);if(!hostile(target()))entityData.set(TARGET,"");return;}}double range=Mpl01Config.RANGE.get();var found=l.getEntities(this,getBoundingBox().inflate(range),this::hostile);found.sort(Comparator.comparingDouble(this::distanceToSqr));var entries=new ListTag();for(var t:found){var n=new CompoundTag();n.putUUID("UUID",t.getUUID());n.putInt("Id",t.getId());n.putString("Name",t.getName().getString());n.putDouble("Distance",distanceTo(t));entries.add(n);if(entries.size()>=32)break;}var n=new CompoundTag();n.put("Entries",entries);entityData.set(CONTACTS,n);if(!hostile(target()))entityData.set(TARGET,"");}
 public boolean deploy(){if(isWreck()||getEnergy()<=0){status("NO ENERGY / load a native SBW battery");return false;}if(phase()==Phase.TRANSPORT){String why=Mpl01Clearance.check(this,true);if(!why.isEmpty()){status(why);return false;}entityData.set(PARK,true);entityData.set(PHASE,1);progress=0;status("DEPLOYING");return true;}if(phase()==Phase.DEPLOYED||phase()==Phase.DEPLOYING){entityData.set(PHASE,3);status("RETRACTING");return true;}return false;}
 public boolean load(ServerPlayer p,int i){if(!operator(p)||i<0||i>3||!getItem(i).isEmpty()||phase()==Phase.DEPLOYING||phase()==Phase.RETRACTING||level().getGameTime()<nextShot)return false;for(int at=0;at<p.getInventory().getContainerSize();at++){var s=p.getInventory().getItem(at);if(s.getItem()!=AddonItems.PM01.get())continue;setItem(i,new ItemStack(AddonItems.PM01.get()));s.shrink(1);p.getInventory().setChanged();entityData.set(FIRED,entityData.get(FIRED)&~(1<<i));setChanged();nextShot=level().getGameTime()+Mpl01Config.RELOAD.get();return true;}status("No PM-01 missile in your inventory");return false;}
 public boolean fire(ServerPlayer p){return operator(p)&&fireImpl(p);}
 private boolean fireImpl(ServerPlayer p){if(phase()!=Phase.DEPLOYED||getEnergy()<=0||level().getGameTime()<nextShot)return false;int i=selectedSlot();if(getItem(i).getItem()!=AddonItems.PM01.get()){status("EMPTY");return false;}var t=target();if(!hostile(t)){status("NO TARGET");return false;}var l=(ServerLevel)level();String clearance=Mpl01Clearance.check(this,true);if(!clearance.isEmpty()){status("BLOCKED: "+clearance);return false;}Vec3 origin=mount(i,1),dir=launchDirection(1);if(!Adv01Targets.clear(l,this,origin,origin.add(dir.scale(6.4)))||!Adv01Targets.clear(l,this,origin.add(dir.scale(3.45)),t.getBoundingBox().getCenter())){status("BLOCKED");return false;}if(Pm01Entity.active(l)>=Mpl01Config.MAX_MISSILES.get()){status("Missile limit reached");return false;}
  var m=AddonEntities.PM01.get().create(l);if(m==null)return false;m.launch(this,p,t,origin,dir);var payload=getItem(i).copy();long previousCooldown=nextShot;removeItem(i,1);entityData.set(FIRED,entityData.get(FIRED)|(1<<i));nextShot=l.getGameTime()+Mpl01Config.RELOAD.get();setChanged();if(!l.addFreshEntity(m)){Pm01Entity.track(l,m.getUUID(),false);nextShot=previousCooldown;setItem(i,payload);entityData.set(FIRED,entityData.get(FIRED)&~(1<<i));setChanged();return false;}consumeEnergy(500);l.playSound(null,origin.x,origin.y,origin.z,com.atsuishio.superbwarfare.init.ModSounds.JAVELIN_FIRE_3P.get(),net.minecraft.sounds.SoundSource.HOSTILE,1f,1f);status("FIRED");return true;
 }
 public void control(ServerPlayer p,int action,int slot,UUID target){if(action<0||action>6||!operator(p)||level().getGameTime()-lastActions[action]<3)return;lastActions[action]=level().getGameTime();if(action==0)deploy();else if(action==1&&phase()==Phase.TRANSPORT)entityData.set(PARK,!entityData.get(PARK));else if(action==2&&slot>=0&&slot<4)entityData.set(SLOT,slot);else if(action==3)load(p,selectedSlot());else if(action==4){var t=((ServerLevel)level()).getEntity(target);if(hostile(t))entityData.set(TARGET,target.toString());}else if(action==5)fire(p);else if(action==6&&phase()==Phase.TRANSPORT){var entries=contacts().getList("Entries",10);if(!entries.isEmpty()){int at=0;for(int i=0;i<entries.size();i++)if(entries.getCompound(i).getUUID("UUID").toString().equals(selectedTarget()))at=(i+1)%entries.size();entityData.set(TARGET,entries.getCompound(at).getUUID("UUID").toString());}}}
 @Override public void baseTick(){super.baseTick();oldPose=visualPose;visualPose=entityData.get(POSE)/1000f;oldWheel=wheel;oldSteer=steer;
  if(level().isClientSide){if(lastVisual!=null){var d=position().subtract(lastVisual);if(d.lengthSqr()<25){var f=getVehicleTransform(1).transformDirection(new org.joml.Vector3d(0,0,1));wheel+=d.dot(new Vec3(f.x,f.y,f.z))/.70;}}lastVisual=position();steer=Mth.approach(steer,parked()?0:leftInputDown()?-.38f:rightInputDown()?.38f:0,.045f);return;}
  if(isWreck()||!isAlive()){entityData.set(PARK,true);entityData.set(CONTACTS,new CompoundTag());entityData.set(TARGET,"");status("DESTROYED");return;}
  if(phase()==Phase.DEPLOYING||phase()==Phase.RETRACTING){if(phase()==Phase.DEPLOYING&&tickCount%10==0){var why=Mpl01Clearance.check(this,false);if(!why.isEmpty()){status("BLOCKED: "+why);return;}}int duration=Mpl01Config.DEPLOY.get();progress=Mth.clamp(progress+(phase()==Phase.DEPLOYING?1:-1),0,duration);if(tickCount%2==0||progress==0||progress==duration)entityData.set(POSE,Math.round(progress*1000f/duration));if(progress==duration){entityData.set(PHASE,2);status("READY");}else if(progress==0&&phase()==Phase.RETRACTING){entityData.set(PHASE,0);status("TRANSPORT / PARK BRAKE");}}
  if(Math.floorMod(level().getGameTime()+getId(),Mpl01Config.SCAN.get())==0)scan();if(tickCount%20==0)syncAmmo();
  if(phase()==Phase.DEPLOYED&&tickCount%5==0){var t=target();String ready=!hostile(t)?"NO TARGET":(ammoMask()&(1<<selectedSlot()))==0?"EMPTY":level().getGameTime()<nextShot?"RELOADING":"READY";if(ready.equals("READY")){var at=mount(selectedSlot(),1);var d=launchDirection(1);if(!Adv01Targets.clear((ServerLevel)level(),this,at,at.add(d.scale(6.4)))||!Adv01Targets.clear((ServerLevel)level(),this,at.add(d.scale(3.45)),t.getBoundingBox().getCenter()))ready="BLOCKED";}status(ready);}
 }
 @Override public InteractionResult interact(Player p,InteractionHand hand){if(isRemoved())return InteractionResult.FAIL;claimOwner(p);if(p.isShiftKeyDown()&&p.getItemInHand(hand).is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)&&(phase()!=Phase.TRANSPORT||getDeltaMovement().horizontalDistance()>.02||!getPassengers().isEmpty()||owner!=null&&!owner.equals(p.getUUID())&&!p.hasPermissions(2))){p.displayClientMessage(Component.literal("Retract, stop and empty both seats before owner/crowbar packing"),true);return InteractionResult.FAIL;}return super.interact(p,hand);}
 @Override public org.joml.Matrix4d getTurretTransform(float p){return launcher(p);}
 @Override public Vec3 getCameraPos(Entity passenger,float p){int seat=getSeatIndex(passenger);return Mpl01Frames.nativePoint(getVehicleTransform(p),seat==0?-.63:.63,2.62,-3.97);}
 @Override public Vec3 getDismountLocationForPassenger(LivingEntity p){for(double x:new double[]{2.7,-2.7,3.5,-3.5})for(double z:new double[]{3.85,1,-3}){var at=Mpl01Frames.point(getVehicleTransform(1),new org.joml.Vector3d(x,.1,z));for(int y=-1;y<=2;y++){var pos=at.add(0,y,0);var box=p.getDimensions(Pose.STANDING).makeBoundingBox(pos);if(level().hasChunkAt(net.minecraft.core.BlockPos.containing(pos))&&level().noCollision(p,box)&&!level().noCollision(p,box.move(0,-.2,0)))return pos;}}return super.dismount(p);}
 @Override public Vec3 getDismountLocationForIndex(LivingEntity p,int i){return getDismountLocationForPassenger(p);}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(owner!=null)n.putUUID("MplOwner",owner);n.putString("MplOwnerName",ownerName);n.putInt("MplPhase",phase().ordinal());n.putInt("MplProgress",progress);n.putInt("MplPose",entityData.get(POSE));n.putInt("MplSlot",selectedSlot());n.putInt("MplFired",entityData.get(FIRED));n.putBoolean("MplPark",entityData.get(PARK));n.put("MplJacks",entityData.get(JACKS));n.putInt("MplCooldown",(int)Math.max(0,nextShot-level().getGameTime()));}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);owner=n.hasUUID("MplOwner")?n.getUUID("MplOwner"):null;ownerName=n.getString("MplOwnerName");int phase=Mth.clamp(n.getInt("MplPhase"),0,3);entityData.set(PHASE,phase);progress=Mth.clamp(n.getInt("MplProgress"),0,Mpl01Config.DEPLOY.get());int pose=Mth.clamp(n.getInt("MplPose"),0,1000);if(phase==0){progress=0;pose=0;}if(phase==2){progress=Mpl01Config.DEPLOY.get();pose=1000;}entityData.set(POSE,pose);visualPose=oldPose=pose/1000f;entityData.set(SLOT,Mth.clamp(n.getInt("MplSlot"),0,3));entityData.set(FIRED,n.getInt("MplFired")&15);entityData.set(PARK,n.getBoolean("MplPark")||phase!=0);entityData.set(JACKS,n.getCompound("MplJacks"));nextShot=level().getGameTime()+Mth.clamp(n.getInt("MplCooldown"),0,Mpl01Config.RELOAD.get());entityData.set(TARGET,"");entityData.set(CONTACTS,new CompoundTag());syncAmmo();}
 @Override public AABB getBoundingBoxForCulling(){return new AABB(getX()-8,getY()-.5,getZ()-8,getX()+8,getY()+11,getZ()+8);}
}
